const ORDER = ['fr', 'en', 'es', 'de', 'it'] as const;

export function pairLead(key: string, locale: Locale): string {
  const row = ROWS[key];
  if (!row) throw new Error(`Duo absent: ${key}`);
  return row[ORDER.indexOf(locale as (typeof ORDER)[number])] ?? row[0];
}

export function pairLeadKeys(): string[] {
  return Object.keys(ROWS);
}
